const fx=c=>c.effects||[],hp=c=>Math.max(0,c.health-c.damage),atk=c=>Math.max(0,c.attack+(c.attackMod||0)),clone=structuredClone;
const profiles={pressao:{face:2.4,board:.8,future:.3,draw:1.3},campo:{face:1.7,board:1.25,future:.65,draw:1.7},recursos:{face:1.3,board:1.15,future:1,draw:2.1}};
function value(c,w){return atk(c)*1.15+hp(c)*.65+fx(c).reduce((s,e)=>s+(e.op==='initiative'?1.7:e.op==='trample'?atk(c)*.25:e.op==='survive_growth'?2*w.future:e.op==='damage_curse'?1:e.op==='kill_growth'?w.future:0),0);}
function forms(p,w){const anchored=p.reserve.filter(c=>c.anchor&&hp(c)>0),free=p.reserve.filter(c=>hp(c)>0&&!p.emanation.includes(c.uid)&&!c.anchor).sort((a,b)=>value(b,w)-value(a,w)).slice(0,5),base=[0,1,2].map(l=>anchored.find(c=>c.anchor.lane===l)?.uid||null),out=[];
 function go(l,slots,used){if(l===3){out.push(slots);return;}if(base[l])return go(l+1,[...slots,base[l]],used);go(l+1,[...slots,null],used);for(const c of free)if(!used.has(c.uid))go(l+1,[...slots,c.uid],new Set([...used,c.uid]));}go(0,[],new Set(base.filter(Boolean)));return out;}
function taunts(p){p.taunts={};for(let l=0;l<3;l++){const c=p.reserve.find(c=>c.uid===p.formation[l]);if(!fx(c||{}).some(e=>e.op==='taunt'))continue;const lane=[l-1,l+1].find(x=>x>=0&&x<3&&!Object.values(p.taunts).includes(x));if(lane!==undefined)p.taunts[c.uid]=lane;}}
function publicRoom(snapshot){const prepared=snapshot.players.flatMap(side=>side.prepared.filter(x=>x.card&&!x.hidden).map(x=>({...clone(x),targetSide:side.id})));const r={...clone(snapshot),events:[],log:[],eventId:0,collectPreview:true,combatCount:snapshot.round-1,preparationsDone:2,phase:'formation'};for(const p of r.players){p.hand=p.hand||[];p.deck=Array.from({length:40},()=>({uid:'forecast',cost:3,type:'unknown'}));p.prepared=prepared.filter(x=>x.caster===p.id);p.formation=p.formation||[null,null,null];p.taunts=p.taunts||{};}return r;}
function bestFormation(api,snap,w){const mine=snap.players.find(p=>p.id===snap.you),enemy=snap.players.find(p=>p.id!==snap.you),candidates=forms(mine,w),enemyForms=forms(enemy,w).filter(f=>f.filter(Boolean).length===Math.min(3,enemy.reserve.filter(c=>hp(c)>0&&!enemy.emanation.includes(c.uid)).length));
 const hypotheses=enemyForms.length?[enemyForms[0],enemyForms[Math.floor(enemyForms.length/2)],enemyForms.at(-1)]:[[null,null,null]];let best=candidates[0],score=-Infinity;
 for(const f of candidates){let total=0;for(const ef of hypotheses){const r=publicRoom(snap),p=r.players.find(p=>p.id===mine.id),q=r.players.find(p=>p.id===enemy.id);p.formation=f;q.formation=ef;taunts(p);taunts(q);api.resolveCombat(r);const ps=p.reserve.reduce((s,c)=>s+value(c,w),0),qs=q.reserve.reduce((s,c)=>s+value(c,w),0);total+=(enemy.patron.hp-q.patron.hp)*w.face-(mine.patron.hp-p.patron.hp)*w.face+ps*w.board-qs*w.board+(r.winner===p.id?1000:r.winner===q.id?-1000:0);}
 if(total>score){score=total;best=f;}}return{slots:best,score:score/hypotheses.length};}
function prep(snap,w){const p=snap.players.find(x=>x.id===snap.you),enemy=snap.players.find(x=>x.id!==p.id),active=p.reserve.filter(c=>!p.emanation.includes(c.uid)&&hp(c)>0),wounds=p.reserve.filter(c=>c.damage>0&&hp(c)>0).sort((a,b)=>b.damage-a.damage),choices=[];
 const healing=p.emanation.filter(uid=>fx(p.reserve.find(c=>c.uid===uid)||{}).some(e=>e.op==='heal')),reserveMana=wounds.length?healing.length:0;
 const add=(action,v,cost)=>{if(cost<=p.mana-reserveMana&&v>.15)choices.push({action,score:v/(1+cost*.55)});};
 for(const c of p.hand){if(c.type==='creature'){if(active.length<8){let v=value(c,w)*w.board+fx(c).filter(e=>e.timing==='on_enter'&&e.op==='draw').reduce((s,e)=>s+e.amount*w.draw,0);if(active.length>=3)v*=.65;add({type:'play',cardId:c.uid},v,c.cost);}if(p.emanation.length<2&&active.length>=2){for(const e of fx(c).filter(e=>String(e.timing).includes('emanat'))){const v=e.op==='heal'?(wounds.length?2.2:active.length>=3?.65:0):e.op==='lane_attack_aura'?1.8+active.length*.2:0;add({type:'play',cardId:c.uid,mode:'emanate'},v,c.cost);}}continue;}
 const e=fx(c)[0];if(!e)continue;
 if(!c.positionOnly){if(e.op==='draw'&&p.hand.length<=7&&p.deckCount>0)add({type:'play',cardId:c.uid,mode:'direct'},e.amount*w.draw-(fx(c).some(x=>x.op==='discard')?.8:0),c.cost);
 if(e.op==='area_stat_buff'&&active.length>=2)add({type:'play',cardId:c.uid,mode:'direct'},p.reserve.reduce((s,t)=>s+e.attack*1.15+e.health*.65,0),c.cost);
 if(e.op==='stat_buff')for(const t of active)add({type:'play',cardId:c.uid,mode:'direct',targetId:t.uid},e.attack*1.15+e.health*.65+(fx(t).some(x=>x.op==='trample'||x.op==='survive_growth')?1:0),c.cost);}
 else{const side=e.op==='anchor'?enemy:p;if(side.reserve.filter(t=>!side.emanation.includes(t.uid)).length){for(let lane=0;lane<3;lane++)if(!side.prepared.some(x=>x.caster===p.id&&x.lane===lane)){const v=e.op==='anchor'?.45:e.op==='barrier'?2.4:e.op==='stat_buff'?e.attack*1.15+e.health*.65:.5;add({type:'play',cardId:c.uid,mode:'lane',lane,targetSide:side.id},v,c.cost);}}}
 }
 choices.sort((a,b)=>b.score-a.score);if(choices.length)return choices[0].action;
 const taken=new Map();let mana=p.mana;const targets=healing.map(uid=>{const ef=fx(p.reserve.find(c=>c.uid===uid)).find(e=>e.op==='heal'&&String(e.timing).includes('emanat'));const t=wounds.find(c=>c.damage>(taken.get(c.uid)||0)&&(!ef.exclude_self||c.uid!==uid));if(!t||mana<(ef.mana_cost||0))return null;mana-=ef.mana_cost||0;taken.set(t.uid,(taken.get(t.uid)||0)+ef.amount);return t.uid;});return{type:'endPrep',healTargetIds:targets};}
const cards=Object.fromEntries(decks.flatMap(d=>d.cards).map(c=>[c.id,{name:c.name,deck:c.affinity,cost:c.cost,drawn:0,played:0,burned:0,discarded:0,combats:0,damage:0,faceDamage:0,growth:0,healing:0,dead:0,unplayed:0}]));
const games=[];
for(let n=0;n<20;n++){let api,room,seed=202610040+n*1000;const wanted=decks[n%2];for(let a=0;a<200;a++,seed++){api=await engine(seed);room=api.makeRoom('SIM'+n,'Forja');const q=api.join(room,'Fluxo');api.act(room,room.players[0],{type:'deck',deckId:decks[0].id},catalog);api.act(room,q,{type:'deck',deckId:decks[1].id},catalog);if(room.players.find(p=>p.id===room.first).deckId===wanted.id)break;}
 const first=room.first,ps=Object.keys(profiles),profile=new Map(room.players.map((p,i)=>[p.id,ps[(Math.floor(n/2)+i)%3]])),trace=[],stats=Object.fromEntries(room.players.map(p=>[p.id,{burned:0,fatigue:0,healing:0,unusedMana:0,draws:0}]));
 for(const p of room.players)for(const c of p.hand)cards[c.modelId].drawn++;
 let last=room.eventId,combats=0,guard=0;
 function collect(){for(const e of room.events.filter(e=>e.id>last)){const s=stats[e.playerId];if(e.type==='draw'){s.draws++;const c=room.players.flatMap(p=>p.hand).find(c=>c.uid===e.cardId);if(c)cards[c.modelId].drawn++;}if(e.type==='burn'){s.burned++;const c=room.players.flatMap(p=>p.discard).findLast(c=>c.name===e.name);if(c)cards[c.modelId].burned++;}if(e.type==='fatigue')s.fatigue+=e.amount;if(e.type==='cleric_heal'){s.healing+=e.amount;const c=room.players.flatMap(p=>p.reserve).find(c=>c.uid===e.sourceId);cards[c.modelId].healing+=e.amount;}}last=room.eventId;}
 function action(p,a){const c=a.cardId?p.hand.find(c=>c.uid===a.cardId):null;api.act(room,p,a,catalog);if(c&&a.type==='play')cards[c.modelId].played++;if(c&&a.type==='discard')cards[c.modelId].discarded++;if(a.type==='endPrep')stats[p.id].unusedMana+=p.mana;trace.push({round:room.round,player:p.name,...a,card:c?.name});collect();}
 while(room.phase!=='finished'&&room.round<=80&&guard++<4000){
  const pending=room.players.find(p=>p.pendingDiscard);if(pending&&room.phase!=='resolving'){action(pending,{type:'discard',cardId:[...pending.hand].sort((a,b)=>b.cost-a.cost)[0].uid});continue;}
  if(room.phase==='mulligan'){for(const p of room.players){if(p.mulliganReady)continue;const ids=p.hand.filter(c=>c.cost>=4).map(c=>c.uid);action(p,p.mulligansLeft&&ids.length?{type:'mulligan',cardIds:ids}:{type:'confirmMulligan'});if(room.phase!=='mulligan')break;}}
  else if(room.phase==='prep'){const expected=room.round%2?first:room.players.find(p=>p.id!==first).id;assert.equal(room.first,expected);const p=room.players.find(p=>p.id===room.turn);action(p,prep(api.view(room,p),profiles[profile.get(p.id)]));}
  else if(room.phase==='vote'){for(const p of room.players){if(room.phase!=='vote')break;const snap=api.view(room,p),w=profiles[profile.get(p.id)],f=bestFormation(api,snap,w);action(p,{type:'vote',fight:f.score>0||room.round>=12});}}
  else if(room.phase==='formation'){for(const p of room.players){if(p.ready)continue;const f=bestFormation(api,api.view(room,p),profiles[profile.get(p.id)]).slots;for(let l=0;l<3;l++)if(p.formation[l]&&!p.reserve.find(c=>c.uid===p.formation[l])?.anchor)action(p,{type:'assign',cardId:null,lane:l});for(let l=0;l<3;l++)if(f[l])action(p,{type:'assign',cardId:f[l],lane:l});const copy=clone(p);taunts(copy);for(const [uid,lane]of Object.entries(copy.taunts))action(p,{type:'taunt',cardId:uid,lane});action(p,{type:'ready'});}}
  else if(room.phase==='resolving'){combats++;const participants=room.players.flatMap(p=>p.formation.map(uid=>p.reserve.find(c=>c.uid===uid)).filter(Boolean));for(const c of participants)cards[c.modelId].combats++;const before=new Map(participants.map(c=>[c.uid,{model:c.modelId,damage:c.damage,attack:c.attack}]));for(const step of room.combat.timeline){if(step.kind==='strike')for(const strike of [step.strike,step.strike.pair].filter(Boolean)){const id=before.get(strike.sourceId)?.model;if(id){cards[id].damage+=strike.blocked?0:strike.amount;cards[id].faceDamage+=strike.patronDamage||0;}}}api.flush();for(const [uid,b]of before){const c=room.players.flatMap(p=>p.reserve).find(c=>c.uid===uid);if(!c)cards[b.model].dead++;else cards[b.model].growth+=Math.max(0,c.attack-b.attack);}collect();}
  else throw Error(room.phase);
 }
 assert.equal(room.phase,'finished');for(const p of room.players)for(const c of p.hand)cards[c.modelId].unplayed++;
 const result={n:n+1,seed,first:room.players.find(p=>p.id===first).patron.affinity,winner:room.players.find(p=>p.id===room.winner)?.patron.affinity||'empate',rounds:room.round,combats,players:room.players.map(p=>({deck:p.patron.affinity,profile:profile.get(p.id),hp:p.patron.hp,deckLeft:p.deck.length,...stats[p.id]})),trace};games.push(result);console.log(`${n+1}/20: ${result.winner}, rodada ${result.rounds}, primeiro ${result.first}`);
}
const summary={games:20,wins:Object.fromEntries(['forja','fluxo','empate'].map(d=>[d,games.filter(g=>g.winner===d).length])),firstWins:games.filter(g=>g.first===g.winner).length,meanRounds:games.reduce((s,g)=>s+g.rounds,0)/20,meanCombats:games.reduce((s,g)=>s+g.combats,0)/20,cards};
const hash=s=>createHash('sha256').update(s).digest('hex');await fs.writeFile(out+'/resultados.json',JSON.stringify({method:'Motor real; 20 partidas; 10 primeiros de cada deck; ordem alternada; 1 troca por jogador; patronos16; decisões só pela visão pública, com três estilos e previsões de formação adversária. Não usa mão, ordem do deck nem formação secreta do rival. Políticas heurísticas, não jogadores humanos.',hashes:Object.fromEntries(Object.entries(sources).map(([k,v])=>[k,hash(v)])),catalogHash:hash(JSON.stringify(catalog)),summary,games},null,2));console.log(JSON.stringify(summary,null,2));
